var machine = getMachine((await listMachines())[0].id)
await machine.waitAndAcquire()
var page = await machine.browser.newtab("https://en.wikipedia.org")
var snap = await page.snapshot()
console.log(snap.snapshot.outline())

// Navigate to Alan Turing
await page.type({ ref: "e24", text: "Alan Turing", submit: true })
await wait({ waitTime: 2 })
var snap = await page.snapshot()

// Extract birth info from the infobox
var turingBirth = snap.snapshot.grep("Born", { context: 2 })
console.log(turingBirth)

var turingDied = snap.snapshot.grep("Died", { context: 1 })
console.log(turingDied)

// Get the URL
var url = await page.url()
console.log("URL: " + url)

